221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
237	     * the canonical form each stored value must take: the address is trimmed,
238	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
239	     * telephone is converted to E.164, any email is lower-cased and a missing
240	     * registration date defaults to today. Field-level rejections are reported here
241	     * rather than inline in {@link #addOwner}, and normalisation runs before any
242	     * household comparison so those comparisons see the canonical values.
243	     *
244	     * @param owner the freshly-mapped owner to normalise
245	     * @return {@code true} if the fields are valid, or {@code false} if the address
246	     *         is blank after normalisation, the telephone cannot form a valid
247	     *         E.164 number, or a supplied registration date is later than the
248	     *         server date, in which case the request must be rejected with
249	     *         {@code 400 Bad Request}
250	     */
251	    private boolean normalizeNewOwner(Owner owner) {
252	        String address = Owner.normalizeAddress(owner.getAddress());
253	        if (address.isEmpty()) {
254	            return false;
255	        }
256	        owner.setAddress(address);
257	        String telephone = toE164(owner.getTelephone());
258	        if (telephone == null) {
259	            return false;
260	        }
261	        owner.setTelephone(telephone);
262	        if (owner.getEmail() != null) {
263	            owner.setEmail(owner.getEmail().toLowerCase());
264	        }
265	        if (!owner.postcodeValidForLocality()) {
266	            return false;
267	        }
268	        if (owner.getRegistrationDate() == null) {
269	            owner.setRegistrationDate(LocalDate.now());
270	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
271	            return false;
272	        }
273	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
274	        return true;
275	    }
276	
277	    /**
278	     * Roll the given date forward to the next business day when it falls on a
279	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
280	     * weekday is returned unchanged. Applied to the effective registration date
281	     * (whether supplied in the request or defaulted to the server date) so that
282	     * every value derived from it uses the adjusted business day.
283	     *
284	     * @param date the effective registration date
285	     * @return the same date if it is a weekday, otherwise the next Monday
286	     */
287	    private static LocalDate rollToBusinessDay(LocalDate date) {
288	        switch (date.getDayOfWeek()) {
289	            case SATURDAY:
290	                return date.plusDays(2);
291	            case SUNDAY:
292	                return date.plusDays(1);
293	            default:
294	                return date;
295	        }
296	    }
297	
298	    /**
299	     * Determine whether the candidate owner's identity key collides with any existing
300	     * owner's. This is the single, consolidated duplicate check: it subsumes the
301	     * former separate telephone, email and household checks by comparing the whole
302	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
303	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
304	     * that agree on some — but not all — of the key's parts (for example two members of
305	     * the same household with different telephones) are not duplicates. Evaluated after
306	     * normalisation and household resolution, so the candidate's key reflects its
307	     * canonical field values and any household it has joined.
308	     *
309	     * @param owner the candidate owner being created, after household resolution
310	     * @return {@code true} if an existing owner has the same identity key
311	     */
312	    private boolean identityKeyAlreadyUsed(Owner owner) {
313	        String identityKey = owner.getIdentityKey();
314	        return this.clinicService.findAllOwners().stream()
315	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
316	    }
317	
318	    /**
319	     * Find an existing owner that belongs to the same household as the given owner,
320	     * i.e. shares the same last name and address (compared case-insensitively with
321	     * runs of whitespace collapsed to a single space).
322	     *
323	     * @param owner the candidate owner being created
324	     * @return the matching existing owner, or empty if none exists
325	     */
326	    private Optional<Owner> findHouseholdMember(Owner owner) {
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> existing.sameHouseholdAs(owner))
329	            .findFirst();
330	    }
331	
332	    /**
333	     * Assign the joining owner and an existing household member the same stable
334	     * household identifier. The identifier is derived deterministically from the
335	     * shared household key (last name + address, normalised), so every owner in a
336	     * household resolves to the same value; the existing member is updated when it
337	     * does not already carry it.
338	     *
339	     * @param owner    the owner being created
340	     * @param existing an existing owner in the same household
341	     */
342	    private void joinHousehold(Owner owner, Owner existing) {
343	        String householdId = UUID
344	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
345	        owner.setHouseholdId(householdId);
346	        if (!householdId.equals(existing.getHouseholdId())) {
347	            existing.setHouseholdId(householdId);
348	            this.clinicService.saveOwner(existing);
349	        }
350	    }
351	
352	    /**
353	     * Assign the owner's computed-at-creation attributes in place: its customer code,
354	     * namesake count, membership number, bulk-signup warning and household size. Unlike
355	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
356	     * derived once here — from the owner's own (already normalised) fields and from the
357	     * wider owner population — and persisted with the owner. Run after normalisation,
358	     * household resolution and the identity-key check, so every value reflects the
359	     * owner's final field values and any household it has joined, and immediately before
360	     * the owner is saved.
361	     *
362	     * <p>Ordering matters: the customer code is assigned first because the membership
363	     * number is built from it.
364	     *
365	     * @param owner the candidate owner being created, after household resolution
366	     */
367	    private void assignDerivedAttributes(Owner owner) {
368	        owner.setCustomerCode(customerCode(owner));
369	        owner.setNamesakeCount(countNamesakes(owner));
370	        owner.setMembershipNumber(membershipNumber(owner));
371	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
372	        owner.setHouseholdSize(householdSize(owner));
373	        assignPossibleDuplicate(owner);
374	    }
375	
376	    /**
377	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
378	     * match — distinct from the hard {@code identityKey} duplicate already rejected with
379	     * 409 — is an existing owner that shares this owner's last name (compared
380	     * case-insensitively) and postcode but carries a different (normalised) telephone.
381	     * When such a match exists the owner is still created, but with
382	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
383	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
384	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
385	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
386	     * are considered.
387	     *
388	     * @param owner the candidate owner being created, after household resolution
389	     */
390	    private void assignPossibleDuplicate(Owner owner) {
391	        String lastName = normalizeName(owner.getLastName());
392	        String postcode = owner.getPostcode();
393	        String telephone = owner.getTelephone();
394	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
395	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
396	                && normalizeName(existing.getLastName()).equals(lastName)
397	                && telephone != null && !telephone.equals(existing.getTelephone()))
398	            .min(Comparator.comparing(Owner::getId));
399	        if (match.isPresent()) {
400	            owner.setPossibleDuplicate(true);
401	            owner.setPossibleDuplicateOf(match.get().getId());
402	        } else {
403	            owner.setPossibleDuplicate(false);
404	            owner.setPossibleDuplicateOf(null);
405	        }
406	    }
407	
408	    /**
409	     * Count how many owners belong to the given owner's household once this create
410	     * completes: the owners that already share its {@code householdId} plus the owner
411	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
412	     * so the household identifier (and any existing member updated to it) is already in
413	     * place. An owner that has not joined a household (no {@code householdId}) is a
414	     * household of one.
415	     *
416	     * @param owner the candidate owner being created, after household resolution
417	     * @return the household member count after this create (at least {@code 1})
418	     */
419	    private int householdSize(Owner owner) {
420	        String householdId = owner.getHouseholdId();
421	        if (householdId == null) {
422	            return 1;
423	        }
424	        long existing = this.clinicService.findAllOwners().stream()
425	            .filter(other -> householdId.equals(other.getHouseholdId()))
426	            .count();
427	        return (int) existing + 1;
428	    }
429	
430	    /**
431	     * Count the existing owners that share the given owner's first and last name,
432	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
433	     * before the new owner is saved, so the result reflects only owners that
434	     * already existed at creation time.
435	     *
436	     * @param owner the candidate owner being created
437	     * @return the number of existing namesakes
438	     */
439	    private int countNamesakes(Owner owner) {
440	        String firstName = normalizeName(owner.getFirstName());
441	        String lastName = normalizeName(owner.getLastName());
442	        return (int) this.clinicService.findAllOwners().stream()
443	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
444	                && normalizeName(existing.getLastName()).equals(lastName))
445	            .count();
446	    }
447	
448	    private static String normalizeName(String value) {
449	        return value == null ? "" : value.trim().toLowerCase();
450	    }
451	
452	    /**
453	     * Determine whether the given city has already reached its owner capacity, i.e.
454	     * it already contains 50 or more existing owners (compared case-insensitively
455	     * with surrounding whitespace trimmed). A new owner may not be created in a city
456	     * that is at capacity.
457	     *
458	     * @param city the candidate owner's city
459	     * @return {@code true} if the city already holds 50 or more owners
460	     */
461	    private boolean cityIsAtCapacity(String city) {
462	        String normalizedCity = normalizeName(city);
463	        long count = this.clinicService.findAllOwners().stream()
464	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
465	            .count();
466	        return count >= 50;
467	    }
468	
469	    /**
470	     * Determine whether the daily owner-creation limit has already been reached, i.e.
471	     * 100 or more owners already carry the given registration date. A new owner may
472	     * not be created once that day's cap is reached.
473	     *
474	     * @param registrationDate the registration date the new owner would be created with
475	     * @return {@code true} if 100 or more existing owners share that registration date
476	     */
477	    private boolean dailyLimitReached(LocalDate registrationDate) {
478	        long count = this.clinicService.findAllOwners().stream()
479	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
480	            .count();
481	        return count >= 100;
482	    }
483	
484	    /**
485	     * Determine whether more than 80 owners have already been created for the given
486	     * registration date, i.e. strictly more than 80 existing owners carry that date.
487	     * Evaluated before the new owner is saved, so it reflects only owners that
488	     * already existed at creation time.
489	     *
490	     * @param registrationDate the registration date the new owner would be created with
491	     * @return {@code true} if more than 80 existing owners share that registration date
492	     */
493	    private boolean bulkSignupWarning(LocalDate registrationDate) {
494	        long count = this.clinicService.findAllOwners().stream()
495	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
496	            .count();
497	        return count > 80;
498	    }
499	
500	    /**
501	     * Build the customer code assigned to the given owner, formatted
502	     * {@code <REGION>-<HASH8>}: REGION is the canonical region derived for the owner
503	     * (see {@link Owner#regionForOwner()}, the postcode-then-city region also exposed
504	     * as its {@link Owner#getLocality() locality}) and HASH8 is the first eight
505	     * upper-case hexadecimal characters of the SHA-256 digest of the owner's
506	     * normalised telephone concatenated with its last name (e.g.
507	     * {@code NSW-9F86D081}). The whole owner is passed so the code can be derived from
508	     * whichever of its (already normalised) fields the identity scheme requires.
509	     *
510	     * @param owner the owner being created, with its fields already normalised
511	     * @return the assigned customer code
512	     */
513	    private String customerCode(Owner owner) {
514	        String region = owner.regionForOwner();
515	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
516	        return String.format("%s-%s", region, hash8);
517	    }
518	
519	    /**
520	     * The first eight upper-case hexadecimal characters of the SHA-256 digest of the
521	     * UTF-8 bytes of the given value.
522	     */
523	    private static String sha256Hex8(String value) {
524	        try {
525	            byte[] digest = MessageDigest.getInstance("SHA-256")
526	                .digest(value.getBytes(StandardCharsets.UTF_8));
527	            StringBuilder hex = new StringBuilder();
528	            for (byte b : digest) {
529	                hex.append(String.format("%02X", b));
530	                if (hex.length() >= 8) {
531	                    break;
532	                }
533	            }
534	            return hex.substring(0, 8);
535	        } catch (NoSuchAlgorithmException e) {
536	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
537	        }
538	    }
539	
540	    /**
541	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
542	     * one place so it stays in step with the owner's identity: it reports the assigned
543	     * customer code alongside the owner's id, registration date and membership level.
544	     *
545	     * @param owner the owner that has just been created and saved
546	     */
547	    private void auditOwnerCreated(Owner owner) {
548	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
549	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
550	    }
551	
552	    /**
553	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
554	     * where {@code <customerCode>} is the owner's already-assigned customer code and
555	     * YY is the last two digits of the registration date's year (e.g.
556	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
557	     * have been set.
558	     *
559	     * @param owner the owner being created, with customer code and registration date
560	     *              already assigned
561	     * @return the assigned membership number
562	     */
563	    private String membershipNumber(Owner owner) {
564	        int yy = owner.getRegistrationDate().getYear() % 100;
565	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
566	    }
567	
568	    /**
569	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
570	     * code when present, otherwise assume country code '+61' and drop a single
571	     * leading '0' from the national digits. Spaces, dashes and brackets are
572	     * stripped. The result must contain 8 to 15 digits after the '+'.
573	     *
574	     * <p>In addition, the national-number length is validated against the country
575	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
576	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
577	     * whose national-number length is wrong for its country code is rejected.
578	     *
579	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
580	     *         input cannot form a valid E.164 number.
581	     */
582	    private static String toE164(String raw) {
583	        if (raw == null) {
584	            return null;
585	        }
586	        String cleaned = raw.replaceAll("[\\s()-]", "");
587	        String digits;
588	        if (cleaned.startsWith("+")) {
589	            digits = cleaned.substring(1);
590	        } else {
591	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
592	            digits = "61" + national;
593	        }
594	        if (!digits.matches("\\d{8,15}")) {
595	            return null;
596	        }
597	        if (!nationalNumberLengthValid(digits)) {
598	            return null;
599	        }
600	        return "+" + digits;
601	    }
602	
603	    /**
604	     * Validate the length of the national number (the digits after the country
605	     * code) against the country code carried by the given E.164 digit string: a
606	     * {@code 61} (Australia) number requires exactly 9 national digits and a
607	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
608	     * without a pinned length are accepted (only the generic 8-15 digit rule
609	     * applies to them).
610	     *
611	     * @param digits the E.164 digits without the leading '+'
612	     * @return {@code true} if the national-number length is correct for the country
613	     */
614	    private static boolean nationalNumberLengthValid(String digits) {
615	        if (digits.startsWith("61")) {
616	            return digits.length() - 2 == 9;
617	        }
618	        if (digits.startsWith("1")) {
619	            return digits.length() - 1 == 10;
620	        }
621	        return true;
622	    }
623	}
