362	     * @return the normalised address, or the empty string if {@code value} is
363	     *         {@code null} or blank
364	     */
365	    public static String normalizeAddress(String value) {
366	        if (value == null) {
367	            return "";
368	        }
369	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
370	        if (collapsed.isEmpty()) {
371	            return "";
372	        }
373	        String[] tokens = collapsed.split(" ");
374	        for (int i = 0; i < tokens.length; i++) {
375	            tokens[i] = switch (tokens[i]) {
376	                case "ST" -> "STREET";
377	                case "RD" -> "ROAD";
378	                case "AVE" -> "AVENUE";
379	                default -> tokens[i];
380	            };
381	        }
382	        return String.join(" ", tokens);
383	    }
