     */
    static String locality(String customerCode, String postcode, String city) {
        if (customerCode != null) {
            int dash = customerCode.indexOf('-');
            if (dash >= 0) {
                return customerCode.substring(0, dash);
            }
        }
        return region(postcode, city);
    }

